import { type ComponentRef, useEffect, useRef } from 'react';
import { GeoJSON, MapContainer, TileLayer, useMap } from 'react-leaflet';

// Generated by OpenAI Codex on 2026-11-03: labels support flat and nested OSM tags.
function onEachFeature(feature: any, layer: any) {
  const properties = feature.properties ?? {};
  const tags = properties.tags ?? properties;
  const text = (value: unknown) => (typeof value === 'string' ? value.trim() : '');
  const kind = ['amenity', 'shop', 'tourism', 'leisure', 'building']
    .map((key) => text(tags[key]))
    .find((value) => value && value !== 'yes');
  const name =
    text(tags.name) ||
    text(tags['name:en']) ||
    text(tags.brand) ||
    `Unnamed ${kind ? kind.replaceAll('_', ' ') : 'location'}`;

  // Leaflet interprets strings as HTML; DOM textContent keeps OSM values safe.
  const label = document.createElement('span');
  label.textContent = name;
  layer.bindTooltip(label, { direction: 'top' });

  const popupContent = document.createElement('div');
  const heading = document.createElement('strong');
  heading.textContent = name;
  popupContent.appendChild(heading);
  const identifier = document.createElement('div');
  identifier.textContent = `OSM: ${feature.id ?? properties.id ?? 'unknown'}`;
  popupContent.appendChild(identifier);
  for (const [key, value] of Object.entries(tags)) {
    const row = document.createElement('div');
    row.textContent = `${key}: ${String(value)}`;
    popupContent.appendChild(row);
  }
  layer.bindPopup(popupContent);
}

// A stable component preserves the map layer across parent renders.
function MapFeatures({ geoJson }: { geoJson: any }) {
  const map = useMap();
  const layerRef = useRef<ComponentRef<typeof GeoJSON>>(null);

  useEffect(() => {
    if (geoJson.features?.length && layerRef.current) {
      const bounds = layerRef.current.getBounds();
      if (bounds.isValid()) {
        map.fitBounds(bounds, { padding: [30, 30] });
      }
    }
  }, [geoJson, map]);

  return (
    <GeoJSON
      ref={layerRef}
      data={geoJson}
      onEachFeature={onEachFeature}
      style={{ color: '#2980b9', weight: 3, opacity: 0.8 }}
    />
  );
}

export default function MapCanvas({ geoJson }: { geoJson: any }) {
  return (
    <div style={{ flex: 1, width: '100%', height: '100%' }}>
      <MapContainer
        center={[43.5853, -84.7732]}
        zoom={13}
        style={{ height: '100%', width: '100%' }}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {geoJson && <MapFeatures key={JSON.stringify(geoJson)} geoJson={geoJson} />}
      </MapContainer>
    </div>
  );
}
